def find_subset(S, target):
    ans = [-1] * len(S)
    total = 0
    for i in range(len(S)):
        if S[i] > target:
            continue
        if total + S[i] > target:
            ans[i] = total = S[i]
            target -= ans[i]
        else:
            total += S[i]
    return ans

def solve(N, K):
    lst = [i for i in range(1, N+1)]
    lst += [-i for i in range(1, N+1)]
    if K == 1:
        print('1 -1', end=' ')
    else:
        if K > len(lst):
            print(*lst, end=' ')
        else:
            L, R = 0, len(lst)-1
            while L < R:
                mid = (L+R+1) // 2
                if find_subset(lst[:mid], K-1) == [-1]:
                    R = mid - 1
                else:
                    L = mid
            ans = find_subset(lst[:L+1], K-1)
            ans += [0]*(len(lst)-L-1)
            print(*ans, end=' ')
```
